import{_ as o,r as a,o as p,c as l,e as n,a as i,s as c}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Radio List Field - October CMS - 4.x","titleTemplate":false,"description":"Form Field","frontmatter":{"subtitle":"Form Field","shortname":"Radio List"},"headers":[{"level":2,"title":"Dynamic Options","slug":"dynamic-options","link":"#dynamic-options","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}],"relativePath":"4.x/element/form/field-radio.md","filePath":"4.x/element/form/field-radio.md"}'),r={name:"4.x/element/form/field-radio.md"};function d(u,s,k,y,g,h){const e=a("pre-heading"),t=a("post-heading");return p(),l("div",null,[n(e),s[0]||(s[0]=i("h1",null,"Radio List Field",-1)),n(t),s[1]||(s[1]=c(`<p>The <code>radio</code> field renders a list of radio options, where only one item can be selected at a time. Radio fields support the same methods for defining the options as the <a href="./field-dropdown.html">dropdown field type</a>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">security_level</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> radio
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Access Level
    <span class="token key atrule">options</span><span class="token punctuation">:</span>
        <span class="token key atrule">all</span><span class="token punctuation">:</span> All
        <span class="token key atrule">registered</span><span class="token punctuation">:</span> Registered only
        <span class="token key atrule">guests</span><span class="token punctuation">:</span> Guests only
</code></pre></div><p>The following <a href="./../form-fields.html">field properties</a> are commonly used.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>a name when displaying the form field to the user.</td></tr><tr><td><strong>default</strong></td><td>a default value to use for new records.</td></tr><tr><td><strong>options</strong></td><td>available options for the radio list, as an array.</td></tr><tr><td><strong>optionsMethod</strong></td><td>take options from a method defined on the model or as a static method, eg <code>Class::method</code>.</td></tr><tr><td><strong>cssClass</strong></td><td>used for setting the options as inline.</td></tr><tr><td><strong>inlineOptions</strong></td><td>display the options side-by-side instead of stacked.</td></tr></tbody></table></div><p>You may use the <code>default</code> property to set a default value, where the value is the key of the option.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">security_level</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> radio
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Access Level
    <span class="token key atrule">default</span><span class="token punctuation">:</span> guests
</code></pre></div><p>In addition to a simple arrays, radio lists support a secondary description as part of their <code>options</code>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">security_level</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> radio
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Access Level
    <span class="token key atrule">options</span><span class="token punctuation">:</span>
        <span class="token key atrule">all</span><span class="token punctuation">:</span> <span class="token punctuation">[</span>All<span class="token punctuation">,</span> Guests and customers will be able to access this page.<span class="token punctuation">]</span>
        <span class="token key atrule">registered</span><span class="token punctuation">:</span> <span class="token punctuation">[</span>Registered only<span class="token punctuation">,</span> Only logged in member will be able to access this page.<span class="token punctuation">]</span>
        <span class="token key atrule">guests</span><span class="token punctuation">:</span> <span class="token punctuation">[</span>Guests only<span class="token punctuation">,</span> Only guest users will be able to access this page.<span class="token punctuation">]</span>
</code></pre></div><p>To visually display the options side-by-side instead of stacked, set the <code>inlineOptions</code> property to a <code>true</code> value.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">security_level</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> radio
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Access Level
    <span class="token key atrule">inlineOptions</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
</code></pre></div><h2 id="dynamic-options"><a href="#dynamic-options" class="header-anchor">#</a> Dynamic Options</h2><p>Radio lists support the same methods for defining the options as the <a href="./field-dropdown.html">dropdown field type</a>.</p><p>In addition to these definitions, for radio lists, the method could return either the simple array: <strong>key =&gt; value</strong> or an array of arrays for providing the descriptions: <strong>key =&gt; [label, description]</strong>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">listAccessLevels</span><span class="token punctuation">(</span><span class="token variable">$fieldName</span><span class="token punctuation">,</span> <span class="token variable">$value</span><span class="token punctuation">,</span> <span class="token variable">$formData</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;all&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;All&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Guests and customers will be able to access this page.&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
        <span class="token comment">// ...</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./field-dropdown.html">Dropdown Form Field</a></li></ul></div>`,16))])}const v=o(r,[["render",d]]);export{f as __pageData,v as default};
